async function sendOrderNotification(payload) {
  const resend = getResend2();
  if (!resend) return;
  const staff = getContactForwardEmails();
  if (staff.length > 0) {
    const { error: error40 } = await resend.emails.send({ from: FROM_EMAIL, to: staff, subject: `New Order ${payload.orderId} \u2014 $${payload.total}`, html: ownerHtml(payload) });
    if (error40) console.error("[email] Owner notification failed:", error40);
    else console.log("[email] Owner notification sent");
  }
  if (payload.customerEmail) {
    const { error: error40 } = await resend.emails.send({ from: FROM_EMAIL, to: [payload.customerEmail], reply_to: "info@allwindowdoorparts.com", subject: `Order Confirmation \u2014 ${payload.orderId}`, html: customerHtml(payload) });
    if (error40) console.error("[email] Customer confirmation failed:", error40);
    else console.log("[email] Customer confirmation sent");
  }
}

