router7.get("/admin/price-alerts", async (_req, res) => {
  try {
    const latestChecks = await db.execute(sql`
      SELECT DISTINCT ON (product_sku, distributor)
        dp.id,
        dp.product_sku,
        dp.distributor,
        dp.distributor_sku,
        dp.distributor_url,
        dp.cost_price,
        dp.our_price,
        dp.markup_ratio,
        dp.target_markup,
        dp.status,
        dp.notes,
        dp.checked_at,
        p.name AS product_name,
        p.category,
        p.supplier
      FROM distributor_prices dp
      LEFT JOIN products p ON p.sku = dp.product_sku
      ORDER BY dp.product_sku, dp.distributor, dp.checked_at DESC
    `);
    const rows = latestChecks.rows;
    const alerts = rows.filter((r2) => r2.status !== "ok");
    const ok = rows.filter((r2) => r2.status === "ok");
    const noPrice = rows.filter((r2) => r2.status === "no_price");
    const needsUpdate = rows.filter((r2) => ["needs_update", "cost_up"].includes(r2.status));
    const costDown = rows.filter((r2) => r2.status === "cost_down");
    const summary = {
      total: rows.length,
      ok: ok.length,
      needsUpdate: needsUpdate.length,
      costDown: costDown.length,
      noPrice: noPrice.length,
      lastChecked: rows[0]?.checked_at ?? null
    };
    res.json({
      summary,
      alerts: rows.sort((a, b3) => {
        const order = { needs_update: 0, cost_up: 1, cost_down: 2, no_price: 3, ok: 4 };
        return (order[a.status] ?? 5) - (order[b3.status] ?? 5);
      })
    });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});
